#!/usr/bin/env bash
# Generated by @navori/plugin-semgrep. Runs semgrep over TS/TSX files changed
# vs the configured base branch with the `p/default` ruleset. Skips silently if
# semgrep or git are absent — the tool is optional.
#
# NOTE: `p/default` (not `auto`) on purpose. `--config=auto` is INCOMPATIBLE
# with `--metrics=off` in semgrep >=1.x ("Cannot create auto config when metrics
# are off") because auto uploads project metadata to fetch tailored rules. A
# static ruleset keeps telemetry off AND runs deterministically — better for a
# gate anyway (same rules on every machine).
#
# Triggered as a PreToolUse(Bash) hook, gated to git commit / push / gh pr
# create — the security scan runs right before code lands or is pushed. Because
# the same content passes that gate up to three times per cycle, a green scan is
# memoized by content fingerprint (see the cache block below, #402).

set -euo pipefail

# Command extraction (payload → $cmd). Shared body, single source of truth.
# navori:include extract-cmd

navori_audit_name="check-semgrep"
navori_audit_phase="PreToolUse"
navori_audit_tool="Bash"
# `source` names the PLUGIN, not core: disabling a plugin changes which hooks
# run, and without this the report cannot explain why a phase thinned out
# between two sessions.
navori_audit_source="plugin:semgrep"
# Fallback no-ops, overwritten by the real definitions the include brings in.
# They exist because this hook is FAIL-OPEN: if the file ever runs WITHOUT its
# includes expanded — a raw copy of the asset, a render that half-finished — an
# undefined function would be exit 127, and under `set -e` that KILLS the hook.
# A recorder that can kill the thing it observes is the one bug this partial may
# never have.
navori_audit_begin() { :; }
navori_audit_log() { :; }
# navori:include audit-log
navori_audit_begin

# Same shape as quality-gate-pre-commit: fires on every Bash call, works on
# almost none, so the verdict comes from the exit code rather than from a call
# per branch.
navori_audit_on_exit() {
  navori_audit_code=$?
  if [ "$navori_audit_code" -eq 0 ]; then
    navori_audit_log "allow" || true
  else
    navori_audit_log "block" "el escaneo de semgrep no paso" || true
  fi
  return 0
}
trap navori_audit_on_exit EXIT

# Gate to `git commit` / `git push` / `gh pr create`: the semgrep copy is the
# only gate that also fires on push and PR creation (remote-push security
# backstop). $TRIGGER_RE is consumed by the shared detector inlined below.
TRIGGER_RE='(^git([[:space:]]+-[a-zA-Z-]+(=[^[:space:]]+)?([[:space:]]+[^-][^[:space:]]*)?)*[[:space:]]+(commit|push)([[:space:]]|$))|(^gh[[:space:]]+pr[[:space:]]+create([[:space:]]|$))'
# navori:include gate-trigger

# Resolution of the working tree the commit acts on (#454). Shared body.
# navori:include resolve-worktree

# No command extracted (empty $cmd) → run unconditionally (defensive fallback). A
# real command that is NOT a scanned op → skip. Anything else → scan.
if [ -n "$cmd" ] && ! is_scan_trigger "$cmd"; then
  exit 0
fi

if ! command -v semgrep >/dev/null 2>&1; then
  echo "⊘ semgrep not installed locally — skip (install: brew install semgrep)" >&2
  exit 0
fi

# This script's own bytes feed the cache fingerprint below, so pin its path
# BEFORE the `cd` (a relative `$0` would stop resolving afterwards). Read at top
# level on purpose: inside a function zsh rebinds `$0` to the function name.
script_path="$0"
case "$script_path" in /*) ;; *) script_path="$PWD/$script_path" ;; esac

# Run from the tree the commit acts on — NOT from the hook process's cwd, which
# is the main repo even when the diff lives in an agent worktree (#454). Also
# keeps changed paths relative, so a repo path with spaces stays robust; the
# NUL-delimited read handles spaces in filenames, and the
# `-- '*.ts' '*.tsx'` pathspec filters by extension without a pipe.
tree=$(navori_worktree)
if [ -z "$tree" ]; then
  echo "⊘ semgrep: no git working tree resolved for this command — skip" >&2
  exit 0
fi
cd "$tree"

# branchBase is shell-quoted at render time via the shq: marker (#197/#249): a
# hostile branchBase in navori.config.json lands here as an inert literal, so it
# can only ever be a branch ref — never an injected command (this hook runs on
# every git commit/push via PreToolUse(Bash)).
base={{shq:branchBase}}

# Resolved to a SHA, not left as a ref: it is BOTH the scan's baseline and part
# of the cache fingerprint below, so it has to name one immutable commit.
base_sha=$(git rev-parse --verify --quiet "$base^{commit}" 2>/dev/null || true)
if [ -z "$base_sha" ]; then
  echo "⊘ branch '$base' does not exist in $tree — skip semgrep" >&2
  exit 0
fi
base_short=$(git rev-parse --short "$base_sha" 2>/dev/null || printf '%s' "$base_sha")

# `git diff` runs inside a process substitution, whose exit status the shell
# never reports, and its stderr used to go to /dev/null — so a diff that FAILED
# (exit 128: unborn HEAD, a corrupt index, a base that vanished mid-run)
# produced zero records and was indistinguishable from "nothing changed": the
# hook printed `0 files to scan` and exited 0 (#511). The sentinel carries the
# status back out of the subshell. It can never collide with a real record: the
# pathspec restricts the list to `*.ts`/`*.tsx`.
diff_sentinel='@navori-diff-status:'
diff_status=""
files=()
while IFS= read -r -d '' f; do
  case "$f" in
    "${diff_sentinel}"*) diff_status="${f#"${diff_sentinel}"}"; continue ;;
  esac
  files+=("$f")
done < <(
  # `|| diff_rc=$?` and not a bare `$?`: the subshell inherits `set -e`, which
  # would kill it on a failing `git diff` before the sentinel is ever written.
  diff_rc=0
  git diff --name-only -z --diff-filter=ACMRT "$base_sha" -- '*.ts' '*.tsx' || diff_rc=$?
  printf '%s%s\0' "$diff_sentinel" "$diff_rc"
)
if [ "$diff_status" != "0" ]; then
  echo "✗ semgrep: \`git diff\` FAILED (exit ${diff_status:-unknown}) in $tree — NOTHING was scanned" >&2
  echo "  this is not a security verdict: no file was compared against $base ($base_short)" >&2
  exit 1
fi

# An empty scan is NOT a silent green (#454): say which tree and which base
# produced it, so "there was nothing to scan" reads differently from "I scanned
# and found nothing". The two used to be indistinguishable, which is how a gate
# that never ran passed for a whole day.
if [ ${#files[@]} -eq 0 ]; then
  echo "⊘ semgrep: 0 files to scan — no *.ts/*.tsx differ from $base ($base_short) in $tree" >&2
  exit 0
fi

# --- Content cache (#402) ----------------------------------------------------
# The gate fires on commit AND push AND `gh pr create`, so one cycle used to
# rescan byte-identical content up to three times at ~4s each. The marker
# records the fingerprint of the last GREEN scan; an exact match skips the
# rescan. The fingerprint covers every input that can flip the verdict:
#
#   1. the scanned paths, in the order the scan receives them;
#   2. the exact bytes of each scanned file — `git hash-object --no-filters`
#      hashes the WORKING-TREE content semgrep reads (`--no-filters` skips
#      gitattributes clean/eol conversion, so the hash is the raw bytes);
#   3. `.semgrepignore`, which semgrep applies to its targets;
#   4. the semgrep binary's identity — path plus `ls -l` (size, mtime and, for
#      the usual symlinked install, the versioned target), so an upgrade in
#      place invalidates instead of inheriting the old ruleset's verdict;
#   5. this script's own bytes — the scan arguments (`--config=p/default`,
#      `--error`) are constants HERE, so a re-render that tightens the ruleset
#      must not inherit a marker earned under the looser one;
#   6. the baseline commit the scan compares against (#454). The verdict is
#      "findings NOT already at $base_sha", so the same bytes legitimately flip
#      from green to red (or back) when the base branch moves.
#
# Untracked files are absent from both the fingerprint and the scan: the file
# list comes from `git diff`, so an untracked file is never scanned and can
# never be masked by a hit. Anything the cache cannot establish (no git dir, no
# `date`, a failing hash) leaves $cache_key empty → full scan. The marker is
# published only if the fingerprint still matches AFTER the scan, so it can
# never attest to bytes semgrep did not read. The cache may turn a green into a
# skip, NEVER an unscanned change into a green.
#
# Marker lifetime, in seconds. The fingerprint pins the scanned bytes and the
# semgrep binary, but NOT the registry rules behind `p/default`, which semgrep
# refetches on its own schedule. The TTL bounds how long a stale ruleset can be
# masked; one hour still covers a full commit → push → PR cycle (minutes). A
# fixed assignment, not `${CACHE_TTL:-3600}`: a gate must not let the
# environment it runs in extend how long its own verdict stays valid.
CACHE_TTL=3600

git_dir=$(git rev-parse --absolute-git-dir 2>/dev/null || true)
now=$(date +%s 2>/dev/null || true)
case "$now" in ''|*[!0-9]*) now="" ;; esac

# A function because the recipe runs TWICE: once before the scan to look the
# marker up, once after it to prove nothing moved underneath (see the write
# below). Writes the fingerprint to stdout; fails if any ingredient is missing.
#
# `|| exit 1` on each hash: the caller tests this function's status with `||`,
# which suppresses errexit inside it, so a failing hash would otherwise just
# drop its line and yield a fingerprint over an incomplete recipe. The braces
# are a pipeline element, hence their own subshell — the exit is local to it and
# collapses the whole key to empty (→ full scan).
semgrep_fingerprint() {
  {
    printf '%s\n' "$semgrep_bin"
    printf '%s\n' "$base_sha"
    ls -ldn "$semgrep_bin" 2>/dev/null || true
    git hash-object --no-filters -- "$script_path" || exit 1
    if [ -f .semgrepignore ]; then
      git hash-object --no-filters -- .semgrepignore || exit 1
    fi
    printf '%s\n' "${files[@]}"
    git hash-object --no-filters -- "${files[@]}" || exit 1
  } | git hash-object --stdin
}

cache_key=""
marker=""
if [ -n "$git_dir" ] && [ -d "$git_dir" ] && [ -n "$now" ]; then
  semgrep_bin=$(command -v semgrep)
  cache_key=$(semgrep_fingerprint) || cache_key=""
  # Per-worktree git dir on purpose: a worktree's `.git` is a FILE, and two
  # worktrees hold different content, so they must not share a marker.
  marker="$git_dir/navori-semgrep-ok"
fi

if [ -n "$cache_key" ] && [ -f "$marker" ]; then
  cached_key=""
  cached_ts=""
  # A truncated or hand-edited marker can only ever MISS: the comparison is on
  # the whole key, and a non-numeric timestamp collapses to 0 (never fresh).
  read -r cached_key cached_ts < "$marker" || true
  case "$cached_ts" in ''|*[!0-9]*) cached_ts=0 ;; esac
  age=$(( now - cached_ts ))
  # A marker from the future (clock skew, restored backup) is not trusted.
  if [ "$cached_key" = "$cache_key" ] && [ "$cached_ts" -gt 0 ] && [ "$age" -ge 0 ] &&
    [ "$age" -lt "$CACHE_TTL" ]; then
    echo "✓ semgrep: diff unchanged since last green scan — skip" >&2
    exit 0
  fi
fi

echo "▶ semgrep: ${#files[@]} changed file(s) vs $base ($base_short) in $tree" >&2

# `--baseline-commit` makes the gate fail on findings this branch INTRODUCES,
# not on debt it inherited (#454). Without it, fixing the worktree resolution
# above would have turned a decorative gate into one that blocks any commit
# touching a file with pre-existing hits — e.g. the 7 findings already in `main`
# under packages/cli/src/lib/marker.ts. semgrep runs the baseline scan in a git
# worktree it creates from that commit, so it needs neither a clean tree nor an
# ancestor relationship (verified on 1.174.0 with unstaged/staged/untracked
# changes, from a linked worktree, and with a diverged base). The cost is a
# second scan pass; the content cache above absorbs the repeats within a cycle.
echo "  baseline: findings already at $base ($base_short) are not blocking" >&2

# `>&2` is not cosmetic (#510): a PreToolUse hook shows the user its stderr and
# swallows its stdout, so the findings themselves — the whole point of the gate
# — used to be written where nobody could read them, leaving only the `▶ …`
# progress line visible.
scan_status=0
semgrep scan \
  --config=p/default \
  --error \
  --metrics=off \
  --baseline-commit "$base_sha" \
  "${files[@]}" >&2 || scan_status=$?

# `--error` maps findings to exit 1; anything above that is semgrep itself
# failing (invalid ruleset, unusable baseline, crash). Say WHY, so a broken
# scanner is never read as a security verdict — and see the exit mapping at the
# bottom, which is where that distinction becomes a decision.
if [ "$scan_status" -gt 1 ]; then
  echo "✗ semgrep: scan FAILED with exit $scan_status (not a findings verdict) — nothing was validated" >&2
elif [ "$scan_status" -eq 1 ]; then
  echo "✗ semgrep: new findings vs $base ($base_short) — BLOCKED" >&2
else
  echo "✓ semgrep: ${#files[@]} file(s) scanned vs $base ($base_short) — no new findings" >&2
fi

# Only a GREEN scan writes the marker: a red one (or a crashed/interrupted run)
# leaves nothing behind, so the retry rescans the same content.
#
# And only a scan whose input never moved: $cache_key was taken BEFORE the scan,
# so a writer racing that window (format-on-save, a watch build, a second agent
# in the same worktree) would have semgrep read content B while the marker
# claims content A — leaving A green without ever being scanned, for a whole
# TTL. Re-taking the fingerprint over the now-warm files costs milliseconds and
# keeps the marker describing exactly the bytes semgrep read.
if [ "$scan_status" -eq 0 ] && [ -n "$cache_key" ]; then
  post_key=$(semgrep_fingerprint) || post_key=""
  if [ "$post_key" = "$cache_key" ]; then
    # stderr silenced on the OUTER group: redirections apply left to right, so
    # `> "$marker" 2>/dev/null` would report its own failure (read-only .git, a
    # marker path that is a directory) on the still-unredirected stderr — which
    # a PreToolUse hook shows to the user. Failing to cache is not an error.
    { printf '%s %s\n' "$cache_key" "$now" > "$marker"; } 2>/dev/null || true
  fi
fi

# PreToolUse EXIT CONTRACT (#510). Claude Code blocks a tool call ONLY on exit
# 2; every other non-zero code is shown to the user and the call PROCEEDS. The
# old `exit "$scan_status"` handed semgrep's own code straight through, and
# `--error` maps findings to 1 — so this gate printed a progress line, listed
# its findings where nobody saw them, and blocked exactly nothing. The two
# outcomes the block above already tells apart become two different decisions:
#
#   findings (1)        → 2. A security VERDICT about this diff: block.
#   scanner broken (>1) → 1. NOT a verdict — nothing was validated, so it is
#                         reported loudly and the call proceeds. Blocking on a
#                         tooling failure would spend the gate's credibility on
#                         a claim it cannot make.
#   clean (0)           → 0.
case "$scan_status" in
  0) exit 0 ;;
  1) exit 2 ;;
  *) exit 1 ;;
esac
